/* Slack DNA — aubergine primary, white surfaces, four-color accents, approachable */
.theme-slack-dna {
  --bg: oklch(0.99 0.002 300);
  --surface: oklch(1 0 0);
  --surface-2: oklch(0.96 0.008 320);
  --fg: oklch(0.24 0.04 320);
  --fg-muted: oklch(0.52 0.03 320);
  --accent: oklch(0.306 0.108 327.1);
  --accent-fg: oklch(1 0 0);
  --accent-2: oklch(0.768 0.130 223.2);
  --line: oklch(0.88 0.01 320);
  --success: oklch(0.65 0.15 150);
  --warning: oklch(0.82 0.16 85);
  --danger: oklch(0.520 0.199 14.6);

  --radius: 0.5rem;
  --radius-sm: 0.25rem;
  --radius-lg: 0.75rem;
  --radius-pill: 9999px;

  --shadow-1: 0 1px 2px oklch(0.24 0.04 320 / 10%);
  --shadow-2: 0 4px 12px -4px oklch(0.24 0.04 320 / 18%);
  --shadow-3: 0 16px 40px -16px oklch(0.24 0.04 320 / 28%);
  --glow: 0 0 0 3px color-mix(in oklab, var(--accent-2) 40%, transparent);

  --border-width: 1px;
  --blur-amount: 0px;

  --font-display: "Lato", sans-serif;
  --font-body: "Lato", sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;

  --tracking-display: -0.02em;
  --label-transform: none;
  --label-tracking: 0.01em;

  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}

.theme-slack-dna h1,
.theme-slack-dna h2,
.theme-slack-dna h3 {
  font-family: var(--font-display);
  letter-spacing: var(--tracking-display);
  font-weight: 800;
}

/* Four-color accent system, rotated across repeated blocks */
.theme-slack-dna li:nth-child(4n + 1) svg {
  color: oklch(0.62 0.15 200);
}
.theme-slack-dna li:nth-child(4n + 2) svg {
  color: oklch(0.68 0.17 145);
}
.theme-slack-dna li:nth-child(4n + 3) svg {
  color: oklch(0.75 0.17 75);
}
.theme-slack-dna li:nth-child(4n + 4) svg {
  color: oklch(0.6 0.2 20);
}

/* signature */
.theme-slack-dna { --font-ui: var(--font-display); }
.theme-slack-dna h1 { font-weight: 800; letter-spacing: -0.03em; }
.theme-slack-dna h2 { border-image: linear-gradient(90deg, #36c5f0, #2eb67d, #ecb22e, #e01e5a) 1; border-bottom: 3px solid; padding-bottom: 0.4rem; }

/* depth */
.theme-slack-dna thead th { background: oklch(0.97 0.01 320); font-size: 0.8em; font-weight: 700; color: var(--fg-muted); border-bottom: 1px solid var(--line); }
.theme-slack-dna td { border-bottom: 1px solid var(--line); }
.theme-slack-dna tbody tr:hover { background: oklch(0.95 0.02 240 / 60%); }
.theme-slack-dna a { color: oklch(0.47 0.12 240); text-decoration: none; }
.theme-slack-dna a:hover { text-decoration: underline; }
.theme-slack-dna kbd { font-family: var(--font-body); font-size: 0.85em; background: var(--surface); border: 1px solid var(--line); border-bottom-width: 2px; border-radius: 0.3rem; padding: 0.1em 0.45em; box-shadow: var(--shadow-1); }
.theme-slack-dna input, .theme-slack-dna textarea, .theme-slack-dna select { border: 1px solid oklch(0.72 0.02 320); border-radius: var(--radius-sm); }
.theme-slack-dna input:focus-visible, .theme-slack-dna textarea:focus-visible, .theme-slack-dna select:focus-visible { outline: none; border-color: var(--accent-2); box-shadow: var(--glow); }
.theme-slack-dna ::selection { background: oklch(0.85 0.07 240); }
.theme-slack-dna ::-webkit-scrollbar { width: 10px; height: 10px; }
.theme-slack-dna ::-webkit-scrollbar-track { background: var(--surface-2); }
.theme-slack-dna ::-webkit-scrollbar-thumb { background: oklch(0.6 0.06 327); border-radius: 5px; border: 2px solid var(--surface-2); }
.theme-slack-dna .label-caps { color: var(--accent); font-weight: 700; }
.theme-slack-dna .themed-border { border-left: 4px solid var(--accent); }
.theme-slack-dna button:active { transform: translateY(1px); }

/* alt mode: aubergine night — Slack's dark client keeps the plum cast */
.theme-slack-dna.alt-mode {
  --bg: oklch(0.17 0.03 327);
  --surface: oklch(0.21 0.035 327);
  --surface-2: oklch(0.25 0.04 327);
  --fg: oklch(0.97 0.005 90);
  --fg-muted: oklch(0.70 0.01 90);
  --line: oklch(1 0 0 / 14%);
  --shadow-1: 0 2px 6px oklch(0 0 0 / 45%);
  --shadow-2: 0 8px 24px oklch(0 0 0 / 55%);
  --shadow-3: 0 24px 56px oklch(0 0 0 / 65%);
  --accent: oklch(0.62 0.108 327.1);
  --accent-fg: oklch(0.13 0 0);
}
.theme-slack-dna.alt-mode thead th { background: oklch(0.24 0.035 327); }
.theme-slack-dna.alt-mode tbody tr:hover { background: oklch(1 0 0 / 6%); }
.theme-slack-dna.alt-mode a { color: oklch(0.70 0.10 240); }
.theme-slack-dna.alt-mode ::selection { background: oklch(0.45 0.08 240); }
.theme-slack-dna.alt-mode kbd { background: var(--surface-2); }
.theme-slack-dna.alt-mode input, .theme-slack-dna.alt-mode textarea, .theme-slack-dna.alt-mode select { border-color: oklch(1 0 0 / 25%); background: var(--surface); }
.theme-slack-dna.alt-mode ::-webkit-scrollbar-thumb { background: oklch(0.5 0.06 327); }

/* Bridge shadcn semantic variables to the theme tokens so stock shadcn/ui
   components are skinned by the theme. Scope-safe: applies inside the theme
   class only. */
[class*="theme-"] {
  --background: var(--bg);
  --foreground: var(--fg);
  --card: var(--surface);
  --card-foreground: var(--fg);
  --popover: var(--surface);
  --popover-foreground: var(--fg);
  --primary: var(--accent);
  --primary-foreground: var(--accent-fg);
  --secondary: var(--surface-2);
  --secondary-foreground: var(--fg);
  --muted: var(--surface-2);
  --muted-foreground: var(--fg-muted);
  --accent-foreground: var(--accent-fg);
  --border: var(--line);
  --input: var(--line);
  --ring: var(--accent);
  --destructive: var(--danger);
  --destructive-foreground: var(--accent-fg);

  /* Full app surface: sidebar, charts, app-level font + shadow + tracking vars.
     These are what real products (shadcn full kit, RootCX-style UI kits) consume —
     without them a retrofit looks half-themed. */
  --sidebar: var(--surface-2);
  --sidebar-foreground: var(--fg);
  --sidebar-primary: var(--accent);
  --sidebar-primary-foreground: var(--accent-fg);
  --sidebar-accent: color-mix(in oklab, var(--accent) 12%, var(--surface-2));
  --sidebar-accent-foreground: var(--fg);
  --sidebar-border: var(--line);
  --sidebar-ring: var(--accent);

  --chart-1: var(--accent);
  --chart-2: var(--accent-2);
  --chart-3: var(--success);
  --chart-4: var(--warning);
  --chart-5: var(--danger);

  --font-sans: var(--font-body);
  --font-heading: var(--font-app, var(--font-display));
  --font-serif: var(--font-display);

  --shadow-2xs: var(--shadow-1);
  --shadow-xs: var(--shadow-1);
  --shadow-sm: var(--shadow-1);
  --shadow: var(--shadow-2);
  --shadow-md: var(--shadow-2);
  --shadow-lg: var(--shadow-3);
  --shadow-xl: var(--shadow-3);
  --shadow-2xl: var(--shadow-3);

  --tracking-normal: 0em;
}

/* Base experience: make the theme own the canvas and native elements even in
   apps that never adopted semantic classes. Scoped to the theme wrapper. */
[class*="theme-"] {
  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}
[class*="theme-"] :is(h1, h2, h3, h4) { font-family: var(--font-display); }
[class*="theme-"] :is(code, pre, kbd, samp) { font-family: var(--font-mono); }
[class*="theme-"] ::selection { background: color-mix(in oklab, var(--accent) 30%, transparent); }

/* OPT-IN HARD MODE — add "sf-enforce" beside the theme class when the host app
   bakes font/shadow/radius literals into its compiled utilities (a var bridge
   cannot beat a literal). Targeted !important, fonts and surfaces only. */
[class*="theme-"].sf-enforce { font-family: var(--font-body) !important; }
[class*="theme-"].sf-enforce :is(h1, h2, h3, h4, [class*="font-heading"]) {
  font-family: var(--font-app, var(--font-display)) !important;
  letter-spacing: var(--tracking-display) !important;
}
/* Data stays data: metrics/KPIs keep the body face with aligned lining figures.
   The display face is for headlines ONLY — never on numbers. Opt specific
   elements INTO the display face with data-sf="display". */
[class*="theme-"] :is([class*="text-2xl"], [class*="text-3xl"], [class*="text-4xl"], [class*="text-5xl"]) {
  font-variant-numeric: lining-nums tabular-nums;
}
[class*="theme-"].sf-enforce [data-sf="display"] {
  font-family: var(--font-display) !important;
  letter-spacing: var(--tracking-display) !important;
}
[class*="theme-"] :is(.sf-num, [data-sf="num"]) {
  font-family: var(--font-body) !important;
  font-variant-numeric: lining-nums tabular-nums;
}
[class*="theme-"].sf-enforce :is(button, [role="button"]) { font-family: var(--font-ui, var(--font-body)) !important; }
[class*="theme-"].sf-enforce :is(code, pre, kbd) { font-family: var(--font-mono) !important; }
[class*="theme-"].sf-enforce :is(.bg-card, [class*="card"]) {
  box-shadow: var(--shadow-2) !important;
  border-radius: var(--radius-lg) !important;
  border: var(--border-width) solid var(--line) !important;
}
[class*="theme-"].sf-enforce :is([class*="shadow-sm"], [class*="shadow-md"]) { box-shadow: var(--shadow-1) !important; }
[class*="theme-"].sf-enforce :is([class*="shadow-lg"], [class*="shadow-xl"]) { box-shadow: var(--shadow-3) !important; }
